def to_base(n, base):
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        rem = n % base
        if rem < 10:
            digits.append(str(rem))
        else:
            digits.append(chr(ord('A') + rem - 10))
        n //= base
    return "".join(reversed(digits))

n = input()
b1 = int(input())
b2 = int(input())

decimal_value = int(n, b1)
print(to_base(decimal_value, b2))
